ST.xhtml:p:
RGeneral1Trigger(CLK := g_biGeneral1ABSOpen OR bGeneral1ABSOpen OR g_bGeneral1ABSOpen OR g_bGeneral1ABSOpenM);
RGeneral1Trigger0(CLK := g_biGeneral1ABSClose OR g_bGeneral1ABSClose OR bGeneral1ABSClose);
RG1StopTrigger(CLK := g_biG1ABS_ActDone);
RTrigger1(CLK := g_bAxisStopFlag);
RTrigger2(CLK := g_bAxisStopFlag_2 OR g_bAxisStopFlag_3);
RTrigger3(CLK := g_bGeneralAxis1AutoMoveControlM);
RTrigger4(CLK := g_bGeneralAxis2AutoMoveControlM);


(*P:轴编号Q:设置的最大移动距离I:1:根据图纸宽度2:高度*)
IF RTrigger3.Q THEN
  g_bGeneralAxis1AutoMoveControlM := FALSE;
  g_bUniversalAxis1MoveDoneM320 := FALSE;
  IF g_dGeneralAxis1AutoMoveType = 1.0 THEN
	dGeneral1TargetPos := g_dGeneralAxis1AutoMoveDistance -g_dBoundRectangleWidth;
  ELSE
    dGeneral1TargetPos := g_dGeneralAxis1AutoMoveDistance +g_dBoundRectangleheight;	
  END_IF;
  nGeneral1ABSState := 1;
  IF g_bSetAuxiliaryAxisSpeed THEN
		dGeneral1TargetVel := g_nAuxiliaryAxisSpeed;
		g_bSetAuxiliaryAxisSpeed := FALSE;
	ELSE
      dGeneral1TargetVel := dGeneral1ABSVel;
    END_IF;
  IF NOT g_bUseCommonAxis1 THEN
    M.ENABLE[334] := 0;
    g_bFinishedM334_1 := FALSE;
    nGeneral1ABSState := 0;
    g_boGeneral1ABSDone := TRUE;
    g_bGeneral1ABSDone := TRUE;
    g_bUniversalAxis1MoveDoneM320 := TRUE;
  END_IF;
  (*IF nGeneral1ABSState <> 0  AND nGeneral1ABSState <> 20 AND g_General1_Axis.NCTOPLC.ACTVELO > g_dCheckAxisIsMovingSpeedSet  THEN
    g_bAxisIsMoveAlarm := TRUE;
    g_bGeneralAxis1AutoMoveControlM:= FALSE;
	nGeneral1ABSState := 40;
  END_IF; *)
END_IF;

IF RTrigger4.Q THEN

	g_bGeneralAxis2AutoMoveControlM := FALSE;
    g_bUniversalAxis2MoveDoneM320 := FALSE;
	IF g_dGeneralAxis2AutoMoveType = 1.0 THEN
		dGeneral2ABSTargetPos := g_dGeneralAxis2AutoMoveDistance -g_dBoundRectangleWidth;
	ELSE
		dGeneral2ABSTargetPos := g_dGeneralAxis2AutoMoveDistance +g_dBoundRectangleheight;	
	END_IF;
  nbGeneral2ABSState := 1;
  IF g_bSetAuxiliaryAxisSpeed THEN
		dGeneral2ABSTargetVel := g_nAuxiliaryAxisSpeed;
		g_bSetAuxiliaryAxisSpeed := FALSE;
	ELSE
      dGeneral2ABSTargetVel := dGeneral2ABSVel;
    END_IF;
  IF NOT g_bUseCommonAxis2 THEN
    M.ENABLE[334] := 0;
    g_bFinishedM334_2 := FALSE;
    nbGeneral2ABSState := 0;
    g_boGeneral2ABSDone := TRUE;
    g_bGeneral2ABSDone := TRUE;
    g_bUniversalAxis2MoveDoneM320 := TRUE;
  END_IF;
  (*
  IF nbGeneral2ABSState <> 0  AND nbGeneral2ABSState <> 20 AND g_General2_Axis.NCTOPLC.ACTVELO > g_dCheckAxisIsMovingSpeedSet    THEN
    g_bAxisIsMoveAlarm := TRUE;
    g_bGeneralAxis2AutoMoveControlM:= FALSE;
  nbGeneral2ABSState := 40;
  END_IF;*)

END_IF;



IF RGeneral1Trigger.Q THEN
  nGeneral1ABSState := 1;
  g_boGeneral1ABSDone := FALSE;

  g_bGeneral1ABSDone := FALSE;
  bGeneral1ABSDone := FALSE;
  g_bG1_AxisInABS :=FALSE;
  IF g_biGeneral1ABSOpen THEN
    dGeneral1TargetPos := g_fiGeneral1ABSPos; 
    dGeneral1TargetVel := g_fiGeneral1ABSVel;
  ELSIF bGeneral1ABSOpen THEN
    dGeneral1TargetPos := dGeneral1ABSPos;
    dGeneral1TargetVel := dGeneral1ABSVel;
    IF g_bPowerOffMoveToTargetPosSetSpeedFlag THEN
      dGeneral1TargetVel := g_dPowerOffMoveToTargetPosSpeed;
    END_IF;
  ELSIF g_bGeneral1ABSOpenM THEN
    IF g_dGeneralAxisABSMoveTypeM = 1.0 THEN
      dGeneral1TargetPos := dGeneral1ABSPos;
    ELSIF g_dGeneralAxisABSMoveTypeM = 0.0 THEN
      dGeneral1TargetPos := 0.0;
    ELSIF g_dGeneralAxisABSMoveTypeM = 2.0 THEN
       dGeneral1TargetPos := g_dGeneralAxisMoveDistanceM;
    END_IF;
    IF g_bSetAuxiliaryAxisSpeed THEN
      dGeneral1TargetVel := g_nAuxiliaryAxisSpeed;
      g_bSetAuxiliaryAxisSpeed := FALSE;
    ELSE
      dGeneral1TargetVel := dGeneral1ABSVel;
    END_IF;
  ELSE
    dGeneral1TargetPos := g_fGeneral1ABSPos;
    dGeneral1TargetVel := g_fGeneral1ABSVel;
  END_IF;
  bGeneral1ABSOpen:= FALSE;
  g_bGeneral1ABSOpen:= FALSE;
  g_bGeneral1ABSOpenM := FALSE;
  IF NOT g_bUseCommonAxis1 THEN
    M.ENABLE[274] := 0;
    g_bExecuteFinishedM274 := FALSE;
    g_bFinishedM274_1 := FALSE;
    nGeneral1ABSState := 0;
    g_boGeneral1ABSDone := TRUE;
    g_bGeneral1ABSDone := TRUE;
  END_IF;
  nFlag := 1;
(*  
  IF nGeneral1ABSState <> 0  AND nGeneral1ABSState <> 20 AND g_General1_Axis.NCTOPLC.ACTVELO > g_dCheckAxisIsMovingSpeedSet  THEN
    g_bAxisIsMoveAlarm := TRUE;
    bGeneral1ABSOpen:= FALSE;
	g_bGeneral1ABSOpen:= FALSE;
	g_bGeneral1ABSOpenM := FALSE;
  END_IF;*)

END_IF;

IF RGeneral1Trigger0.Q THEN
  g_boGeneral1ABSDone := FALSE;
  g_bGeneral1ABSDone := FALSE;
  bGeneral1ABSDone := FALSE;
  nGeneral1ABSState := 0;
  bGeneral1ABSClose := FALSE;
  g_bGeneral1ABSClose := FALSE;
  g_boG1ABS_ActBck :=FALSE;
END_IF;

IF RG1StopTrigger.Q THEN
  g_boG1ABS_ActBck :=FALSE;
  nGeneral1ABSState :=50;
END_IF;

IF RTrigger1.Q THEN
  IF g_nAxisStopP = 2 THEN
    g_bAxisStopFlag := FALSE;
    nGeneral1ABSState := 40;
  ELSIF g_nAxisStopP = 3 THEN
    g_bAxisStopFlag := FALSE;
    nbGeneral2ABSState := 40;
  END_IF;
END_IF;

IF RTrigger2.Q THEN
  IF g_bAxisStopFlag_2 THEN
    g_bAxisStopFlag_2 := FALSE;
    nGeneral1ABSState := 40;
  END_IF;
  IF g_bAxisStopFlag_3 THEN
    g_bAxisStopFlag_3 := FALSE;
    nbGeneral2ABSState := 40;
  END_IF;
END_IF;

CASE nGeneral1ABSState OF
  0:
    g_bG1_AxisInABS :=FALSE;
    nGeneral1ABSState := 0;
  1:
    g_General1_ABS.Execute := TRUE;
    g_General1_ABS.Velocity := dGeneral1TargetVel;
    g_General1_ABS.Position := dGeneral1TargetPos;

    g_bG1_AxisInABS :=TRUE;
    IF ABS(dGeneral1TargetPos - g_General1_Axis.NCTOPLC.ACTPOS) <= g_diG1SlowLength AND g_diG1Override<>0.0 THEN(*送料倍率选择*)
      g_General1_Override.VELFACTOR := g_dCurOverride*g_diG1Override;
    ELSE
      g_General1_Override.VELFACTOR := g_dCurOverride;
    END_IF; 
    IF g_General1_ABS.Done THEN
      g_General1_ABS.Execute := FALSE;
      g_boGeneral1ABSDone := TRUE;
      g_bGeneral1ABSDone := TRUE;
      bGeneral1ABSDone := TRUE;
      nGeneral1ABSState := 0;
      M.ENABLE[274] := 0;
      M.ENABLE[334] := 0;
      g_bUniversalAxis1MoveDoneM320 := TRUE;
      g_bExecuteFinishedM274 := FALSE;
      g_bFinishedM274_1 := FALSE;
      g_bFinishedM334_1 := FALSE;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nGeneral1ABSState := 20;
    END_IF;
    IF g_General1_ABS.CommandAborted OR g_General1_ABS.Error THEN
      g_General1_ABS.Execute := FALSE;
      g_boGeneral1ABSDone := FALSE;
      g_bGeneral1ABSDone := FALSE;
      bGeneral1ABSDone := FALSE;
      nGeneral1ABSState := 0;
      M.ENABLE[274] := 0;
      M.ENABLE[334] := 0;
      g_bUniversalAxis1MoveDoneM320 := TRUE;
      g_bExecuteFinishedM274 := FALSE;
      g_bFinishedM274_1 := FALSE;
      g_bFinishedM334_1 := FALSE;
		nFlag := 999;
    END_IF;
  20:
    g_General1_ABS.Execute := FALSE;
    g_General1_Stop.Execute := TRUE;
    IF g_General1_Stop.Done AND g_bPlcStartBuffer THEN
      g_General1_Stop.Execute := FALSE;
      nGeneral1ABSState := 1;
    END_IF;
    IF g_General1_Stop.CommandAborted OR g_General1_Stop.Error THEN
      g_General1_Stop.Execute := FALSE;
      nGeneral1ABSState := 0;
    END_IF;
  40:
    g_General1_ABS.Execute := FALSE;
    g_General1_Stop.Execute := TRUE;
    IF g_General1_Stop.Done THEN
      g_General1_Stop.Execute := FALSE;
      g_boG1ABS_ActBck :=TRUE;
      g_bFinishedM325_2 := FALSE;
      M.ENABLE[325] := 0;
      nGeneral1ABSState := 0;
      g_bUniversalAxis1MoveDoneM320 := TRUE;
    END_IF;
    IF g_General1_Stop.COMMANDABORTED OR g_General1_Stop.Error THEN
      g_General1_Stop.Execute := FALSE;
      g_bFinishedM325_2 := FALSE;
      M.ENABLE[325] := 0;
      nGeneral1ABSState := 0;
    END_IF;
  50:
    g_General1_ABS.Execute := FALSE;
    g_General1_Reset.Execute := TRUE;
    IF g_General1_Reset.Done THEN
      g_General1_Reset.Execute := FALSE;
      g_boG1ABS_ActBck :=TRUE;
      nGeneral1ABSState := 0;
    END_IF;
    IF g_General1_Reset.Error THEN
      g_General1_Reset.Execute := FALSE;
      nGeneral1ABSState := 0;
    END_IF;
END_CASE;

RGeneral2Trigger(CLK := g_biGeneral2ABSOpen OR bGeneral2ABSOpen OR g_bGeneral2ABSOpen OR g_bGeneral2ABSOpenM);
RGeneral2Trigger0(CLK := g_biGeneral2ABSClose OR g_bGeneral2ABSClose OR bGeneral2ABSClose);
RG2StopTrigger(CLK := g_biG2ABS_ActDone);
IF RGeneral2Trigger.Q THEN
  nbGeneral2ABSState := 1;
  g_boGeneral2ABSDone := FALSE;
  g_bGeneral2ABSDone := FALSE;
  bGeneral2ABSDone := FALSE;
  g_bG2_AxisInABS :=FALSE;
  IF g_biGeneral2ABSOpen THEN
    dGeneral2ABSTargetPos := g_fiGeneral2ABSPos; 
    dGeneral2ABSTargetVel := g_fiGeneral2ABSVel;
  ELSIF bGeneral2ABSOpen THEN
    dGeneral2ABSTargetPos := dGeneral2ABSPos;
    dGeneral2ABSTargetVel := dGeneral2ABSVel;
    IF g_bPowerOffMoveToTargetPosSetSpeedFlag THEN
      dGeneral2ABSTargetVel := g_dPowerOffMoveToTargetPosSpeed;
    END_IF;
  ELSIF g_bGeneral2ABSOpenM THEN
     IF g_dGeneralAxisABSMoveTypeM = 1.0 THEN
      dGeneral2ABSTargetPos := dGeneral2ABSPos;
    ELSE
      dGeneral2ABSTargetPos := g_dGeneralAxisMoveDistanceM;
    END_IF;
    IF g_bSetAuxiliaryAxisSpeed THEN
      dGeneral2ABSTargetVel := g_nAuxiliaryAxisSpeed;
      g_bSetAuxiliaryAxisSpeed := FALSE;
    ELSE
      dGeneral2ABSTargetVel := dGeneral2ABSVel;
    END_IF;  
  ELSE
    dGeneral2ABSTargetPos := g_fGeneral2ABSPos;
    dGeneral2ABSTargetVel := g_fGeneral2ABSVel;
  END_IF;
  bGeneral2ABSOpen := FALSE;
  g_bGeneral2ABSOpen := FALSE;
  nPos1 := g_General2_Axis.NCTOPLC.ACTPOS;
  g_bGeneral2ABSOpenM := FALSE;
   IF NOT g_bUseCommonAxis2 THEN
    M.ENABLE[274] := 0;
    g_bExecuteFinishedM274 := FALSE;
    g_bFinishedM274_2 := FALSE;
    nbGeneral2ABSState := 0;
    g_boGeneral2ABSDone := TRUE;
    g_bGeneral2ABSDone := TRUE;
  END_IF;

(*  IF nbGeneral2ABSState <> 0  AND nbGeneral2ABSState <> 20 AND g_General2_Axis.NCTOPLC.ACTVELO > g_dCheckAxisIsMovingSpeedSet  THEN
    g_bAxisIsMoveAlarm := TRUE;
    bGeneral2ABSOpen:= FALSE;
	g_bGeneral2ABSOpen:= FALSE;
	g_bGeneral2ABSOpenM := FALSE;
  END_IF;*)

END_IF;

IF RGeneral2Trigger0.Q THEN
  g_boGeneral2ABSDone := FALSE;
  g_bGeneral2ABSDone := FALSE;
  bGeneral2ABSDone := FALSE;
  nbGeneral2ABSState := 0;
  bGeneral2ABSClose := FALSE;
  g_bGeneral2ABSClose := FALSE;
  g_boG2ABS_ActBck :=FALSE;
END_IF;
IF RG2StopTrigger.Q THEN
  g_boG2ABS_ActBck :=FALSE;
  nbGeneral2ABSState :=50;
END_IF;
IF g_nMachineType = 15 OR g_nMachineType =17 THEN
  dFeedtLrngth :=g_diG2SlowLength;
END_IF;

CASE nbGeneral2ABSState OF
  0:
    g_bG2_AxisInABS :=FALSE;
    nbGeneral2ABSState := 0;
  1:
    IF ABS(g_General2_Axis.NCTOPLC.ACTPOS- nPos1) >= dFeedtLrngth AND g_diG2Override<>0.0 AND( g_nMachineType = 15 OR g_nMachineType=17 OR g_nMachineType=20) THEN
      g_General2_Override.VELFACTOR := g_dCurOverride*g_diG2Override;
    ELSE
      g_General2_Override.VELFACTOR := g_dCurOverride;
    END_IF;  

    g_General2_ABS.Execute := TRUE;
    g_General2_ABS.Position := dGeneral2ABSTargetPos;
    g_General2_ABS.Velocity := dGeneral2ABSTargetVel;

    g_bG2_AxisInABS :=TRUE;
    IF g_General2_ABS.Done THEN
      g_General2_ABS.Execute := FALSE;
      g_boGeneral2ABSDone := TRUE;
      g_bGeneral2ABSDone := TRUE;
      bGeneral2ABSDone := TRUE;
      g_bUniversalAxis2MoveDoneM320 := TRUE;
      nbGeneral2ABSState := 0;
      M.ENABLE[274] := 0;
      M.ENABLE[334] := 0;
      g_bExecuteFinishedM274 := FALSE;
      g_bFinishedM274_2 := FALSE;
      g_bFinishedM334_2 := FALSE;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nbGeneral2ABSState := 20;
    END_IF;
    IF g_General2_ABS.CommandAborted OR g_General2_ABS.Error THEN
      g_General2_ABS.Execute := FALSE;
      g_boGeneral2ABSDone := FALSE;
      g_bGeneral2ABSDone := FALSE;
      bGeneral2ABSDone := FALSE;
      nbGeneral2ABSState := 0;
    END_IF;
  20:
    g_General2_ABS.Execute := FALSE;
    g_General2_Stop.Execute := TRUE;
    IF g_General2_Stop.Done AND g_bPlcStartBuffer THEN
      g_General2_Stop.Execute := FALSE;
      nbGeneral2ABSState := 1;
    END_IF;
    IF g_General2_Stop.CommandAborted OR g_General2_Stop.Error THEN
      g_General2_Stop.Execute := FALSE;
      nbGeneral2ABSState := 0;
    END_IF;
  40:
    g_General2_ABS.Execute := FALSE;
    g_General2_Stop.Execute := TRUE;
    IF g_General2_Stop.Done THEN
      g_General2_Stop.Execute := FALSE;
      g_boG2ABS_ActBck :=TRUE;
      g_bFinishedM325_3 := FALSE;
      M.ENABLE[325] := 0;
      nbGeneral2ABSState := 0;
      g_bUniversalAxis2MoveDoneM320 := TRUE;
    END_IF;
    IF g_General2_Stop.CommandAborted OR g_General2_Stop.Error THEN
      g_General2_Stop.Execute := FALSE;
      g_bFinishedM325_3 := FALSE;
      M.ENABLE[325] := 0;
      nbGeneral2ABSState := 0;
    END_IF;
  50:
    g_General2_ABS.Execute := FALSE;
    g_General2_Reset.Execute := TRUE;
    IF g_General2_Reset.Done THEN
      g_General2_Reset.Execute := FALSE;
      g_boG2ABS_ActBck :=TRUE;
      nbGeneral2ABSState := 0;
    END_IF;
    IF g_General2_Reset.Error THEN
      g_General2_Reset.Execute := FALSE;
      nbGeneral2ABSState := 0;
    END_IF;
END_CASE;
IF g_bPlcResetBuffer THEN
  nPos1 :=0.0;
  g_bG1_AxisInABS :=FALSE;
  g_bG2_AxisInABS :=FALSE;
  g_boG1ABS_ActBck :=FALSE;
  g_boG2ABS_ActBck :=FALSE;
  IF g_bRealTimeUpdateParallePLCExecuteFlag AND nGeneral1ABSState <> 0 AND  (g_bExecuteFinishedM274 OR 
    g_bFinishedM274_1 OR g_bFinishedM325_2 OR g_bFinishedM334_1) THEN
    ;
  ELSE
    nGeneral1ABSState := 0;
      g_bExecuteFinishedM274 := FALSE;
      g_bFinishedM274_1 := FALSE;
      g_bFinishedM334_1 := FALSE;
  END_IF;

  g_boGeneral1ABSDone := FALSE;
  g_bGeneral1ABSDone := FALSE;
  bGeneral1ABSDone := FALSE;
  g_General1_ABS.Execute := FALSE;
  g_General1_Stop.Execute := FALSE;
  IF g_bRealTimeUpdateParallePLCExecuteFlag AND nbGeneral2ABSState <> 0 AND (g_bExecuteFinishedM274 OR
     g_bFinishedM274_2 OR g_bFinishedM325_3 OR g_bFinishedM334_2) THEN
    ;
  ELSE
	nbGeneral2ABSState := 0;
      g_bExecuteFinishedM274 := FALSE;
      g_bFinishedM274_2 := FALSE;
      g_bFinishedM334_2 := FALSE;
  END_IF;
  g_boGeneral2ABSDone := FALSE;
  g_bGeneral2ABSDone := FALSE;
  bGeneral2ABSDone := FALSE;
  g_General2_ABS.Execute := FALSE;
  g_General2_Stop.Execute := FALSE;
END_IF;
